using System.Drawing.Design;
using System.Windows.Forms;
using System.Windows.Forms.Design;
public class MyControl : UserControl
{
    private StatusStrip _statusStrip;

    public string DisplayName { get; set; }
    public int MaxItems { get; set; }

    public MyControl()
    {
        _statusStrip = new StatusStrip();
        // .NET 9 breaking change: the default ToolStrip renderer now follows
        // System.Windows.Forms.ToolStripManager.RenderMode, which may differ
        // from the .NET 8 behaviour. Pin to Professional for consistent look.
        _statusStrip.RenderMode = ToolStripRenderMode.Professional;
        Controls.Add(_statusStrip);
    }

    // .NET 9 breaking change: IWindowsFormsEditorService.DropDownControl
    // now throws ArgumentNullException when passed null.
    // Always guard the argument before calling.
    public static void SafeDropDown(IWindowsFormsEditorService editorService, Control control)
    {
        ArgumentNullException.ThrowIfNull(control);
        editorService.DropDownControl(control);
    }
}

